contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, bytes32 h) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= amount);
        uint cb0 = address(c).balance;
        uint tb0 = address(this).balance;
        c.lockInGuess{value: amount}(h);
        c.settle();
        assert(
            (address(c).balance == cb0 + amount && address(this).balance == tb0 - amount) ||
            (address(c).balance == 0 && address(this).balance == tb0 - amount + 2 ether)
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, bytes32 h) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= amount + amount);
        c.lockInGuess{value: amount}(h);
        uint cbAfterLock = address(c).balance;
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }
        assert(reverted && address(c).balance == cbAfterLock && address(this).balance == (2 * amount) - amount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 h1, bytes32 h2, uint amount) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= 2 * amount);
