contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 g, uint amount) public payable {
        require(address(this).balance >= amount);
        uint balBefore = address(c).balance;
        bool lockReverted;
        try c.lockInGuess{value: amount}(g) { lockReverted = false; }
        catch { lockReverted = true; }
        if (amount != 1 ether) {
            assert(lockReverted && address(c).balance == balBefore);
        } else {
            assert(!lockReverted && address(c).balance == balBefore + 1 ether);
        }
    }
    receive() external payable {}
}

